import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Малые туры по Карелии: сайт с каталогом туров, блогом и заявками на заезд"}>
      <p>{"Мы небольшая турфирма из Петрозаводска, водим группы до 12 человек по Карелии: сплавы, пешие маршруты, зимние поездки на снегоходах. Нужен сайт из нескольких разделов: каталог туров (у каждого тура страница с программой по дням, сложностью, ценой, датами заездов и фото), блог с отчётами из поездок и советами, что взять с собой, страница о гидах, частые вопросы и контакты. Посетитель выбирает тур и дату заезда и оставляет заявку: имя, телефон, сколько человек. Заявки приходят менеджеру на почту, он перезванивает и подтверждает. Оплату на сайте пока не принимаем — только заявка. Туры, даты и статьи меняет менеджер сам. Хотим, чтобы сайт выглядел живо, как журнал о путешествиях, а не как шаблон турагентства. Иностранцам часто пишет наш гид клиент, его аккаунт клиент можно дать на странице контактов."}</p>
      <ul>
        <li>{"Каталог туров"}</li>
        <li>{"Программа по дням"}</li>
        <li>{"Блог"}</li>
        <li>{"Заявка на заезд"}</li>
      </ul>
      <p>{"Заявка приходит менеджеру на почту"}</p>
      <p>{"Менеджер сам меняет туры и даты"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
